import { languageSelector } from "~/renderer/reducers/settings";

/** Maps the app language to the locale segment used on www.ledger.com. */
const WWW_LOCALE_MAP: Record<string, string> = {
  pt: "pt-br",
  zh: "zh-hans",
};

/** Maps the app language to the locale segment used on support.ledger.com. */
const SUPPORT_LOCALE_MAP: Record<string, string> = {
  fr: "fr-fr",
  en: "en-us",
  zh: "zh-cn",
};

/** Maps the app language to the locale segment used on shop.ledger.com. */
const SHOP_LOCALE_MAP: Record<string, string> = {
  pt: "pt-br",
};

/**
 * Localizes URLs pointing to Ledger's web properties based on the language
 * currently set in the app.
 *
 * - www.ledger.com: the locale is inserted right after the domain root.
 * - support.ledger.com: the locale is inserted between "/hc/" and the rest of
 *   the path.
 * - shop.ledger.com: the locale is inserted right after the domain root.
 *
 * Any other domain (or an unparsable URL) is returned unchanged.
 *
 * @param url the URL to localize
 * @returns the localized URL, or the original URL when it cannot be localized
 */
export function useLocalizedUrl(url: string): string {
  const language = useSelector(languageSelector);

  let hostname: string;
  let origin: string;
  try {
    const parsed = new URL(url);
    hostname = parsed.hostname;
    origin = parsed.origin;
  } catch {
    return url;
  }

  switch (hostname) {
    case "www.ledger.com": {
      const localeCode = WWW_LOCALE_MAP[language] ?? language;
      return url.replace(origin, `${origin}/${localeCode}`);
    }
    case "support.ledger.com": {
      const localeCode = SUPPORT_LOCALE_MAP[language] ?? language;
      return url.replace("/hc/", `/hc/${localeCode}/`);
    }
    case "shop.ledger.com": {
      const localeCode = SHOP_LOCALE_MAP[language] ?? language;
      return url.replace(origin, `${origin}/${localeCode}`);
    }
    default:
      return url;
  }
}
